import Link from "next/link";
import { PublicFooter } from "@/components/public-footer";
import { PublicHeader } from "@/components/public-header";
import type { InterfaceLanguage } from "@/lib/i18n/config";
import { getMarketingTranslations } from "@/lib/i18n/marketing";

export function LegalPage({ locale, signedIn, type }: { locale: InterfaceLanguage; signedIn: boolean; type: "privacy" | "terms" }) { const t = getMarketingTranslations(locale).legal; const title = type === "privacy" ? t.privacyTitle : t.termsTitle; const intro = type === "privacy" ? t.privacyIntro : t.termsIntro; const sections = type === "privacy" ? t.privacySections : t.termsSections; return <main className="min-h-screen bg-slate-50 text-slate-900"><PublicHeader locale={locale} signedIn={signedIn} /><div className="mx-auto grid max-w-6xl gap-10 px-5 py-12 sm:px-6 sm:py-16 lg:grid-cols-[14rem_minmax(0,1fr)]"><aside className="hidden lg:block"><nav className="sticky top-6 rounded-2xl border border-slate-200 bg-white p-4" aria-label={locale === "vi" ? "Mục lục" : "Table of contents"}><p className="mb-3 text-sm font-black uppercase tracking-wider text-slate-500">{locale === "vi" ? "Mục lục" : "Contents"}</p>{sections.map((section, index) => <a className="block rounded-lg px-2 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50 focus-visible:outline-2 focus-visible:outline-teal-700" href={`#legal-${index}`} key={section.title}>{section.title}</a>)}</nav></aside><article className="min-w-0 max-w-3xl"><Link className="font-bold text-teal-700" href="/">← {t.back}</Link><p className="mt-8 text-sm font-black uppercase tracking-wider text-teal-700">{t.beta}</p><h1 className="mt-3 text-4xl font-black tracking-tight">{title}</h1><p className="mt-3 text-sm text-slate-500">{t.updated}</p><p className="mt-6 text-lg leading-8 text-slate-600">{intro}</p><nav className="mt-8 rounded-2xl border border-slate-200 bg-white p-4 lg:hidden" aria-label={locale === "vi" ? "Mục lục" : "Table of contents"}>{sections.map((section, index) => <a className="block py-2 font-semibold text-teal-800" href={`#legal-${index}`} key={section.title}>{section.title}</a>)}</nav><div className="mt-10 space-y-10">{sections.map((section, index) => <section className="scroll-mt-6" id={`legal-${index}`} key={section.title}><h2 className="text-xl font-black">{section.title}</h2><p className="mt-3 leading-7 text-slate-600">{section.body}</p></section>)}</div></article></div><PublicFooter locale={locale} /></main>; }
